// Beat sheet (30fps, speed 1):
//   0–9    the card slams up and open from its centre line, a little over-scaled
//   3–14   a light sweep crosses the card face; the frame kicks on landing
//   5–20   the giant "MVP" rises letter by letter right of the card, filled
//          with the "fluted" gradient, cap bottom on the card's bottom edge
//  11–23   logo, role tag, kicker and event line slide in
//  18–62   three stats count (the bug count runs down), staggered 8f, each
//          lights its marker when it lands
//  62–     poster hold
const SLAM = Easing.bezier(0.12, 0.9, 0.25, 1);
const OUT = Easing.bezier(0.22, 1, 0.36, 1);
const COUNT = Easing.bezier(0.3, 0.6, 0.15, 1);
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

// gradients.sh "fluted": bg #050507, [#1d2a8f, #2f7bff, #ff7a3d, #ffe2c4].
const FLUTED = ["#1D2A8F", "#2F7BFF", "#FF7A3D", "#FFE2C4"] as const;

// Antonio 500 advance widths (em) for caps, plus its cap height and the
// baseline position inside a line-height: 1 box.
const ADV: Record<string, number> = {
  A: 0.445,
  B: 0.455,
  C: 0.454,
  D: 0.471,
  E: 0.373,
  F: 0.369,
  G: 0.465,
  H: 0.486,
  I: 0.247,
  J: 0.435,
  K: 0.451,
  L: 0.345,
  M: 0.645,
  N: 0.5,
  O: 0.466,
  P: 0.441,
  Q: 0.466,
  R: 0.464,
  S: 0.409,
  T: 0.315,
  U: 0.472,
  V: 0.436,
  W: 0.656,
  X: 0.399,
  Y: 0.409,
  Z: 0.343,
  " ": 0.2,
};
const CAP = 0.859;
const BASELINE = 1.008;

const THEMES = {
  dark: {
    stage: "#060608",
    card: "#111114",
    edge: "#26262C",
    rule: "#222228",
    ink: "#F3F2EF",
    dim: "#86858C",
    title: (a: number) =>
      `linear-gradient(${172 + a}deg, ${FLUTED[3]} 0%, ${FLUTED[2]} 30%, #B2507A 52%, ${FLUTED[1]} 76%, ${FLUTED[0]} 100%)`,
  },
  light: {
    stage: "#F5F4F0",
    card: "#FFFFFF",
    edge: "#E3E1DA",
    rule: "#ECEAE4",
    ink: "#121214",
    dim: "#7E7D77",
    title: (a: number) =>
      `linear-gradient(${172 + a}deg, ${FLUTED[2]} 0%, #C9466A 34%, ${FLUTED[1]} 70%, ${FLUTED[0]} 100%)`,
  },
} as const;

function ramp(t: number, from: number, len: number) {
  return interpolate(t, [from, from + len], [0, 1], CLAMP);
}

/** A hit: up in 1 frame, eases back over `len`. */
function kick(d: number, len = 8) {
  if (d < 0) return 0;
  if (d < 1) return d;
  const k = Math.max(0, 1 - (d - 1) / len);
  return k * k;
}

const midway = (p: number) => p > 5e-4 && p < 1 - 5e-4;

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function MvpCardBase(props: MvpCardProps) {
  const {
    title = "MVP",
    kicker = "Most valuable player",
    event = "Grand final 2026",
    role = "Carry",
    number = "01",
    stats = DEFAULT_MVP_STATS,
    accent = "#3B5BFD",
    ink,
    background,
    fontFamily = antonio,
    logo,
    scale = 1,
    delay = 0,
    theme = "dark",
    speed = 1,
    timing,
  } = props;
  const glide = useGlide();
  const t = Math.max(0, useSceneFrame() - delay) * speed + 1;
  const { width: W, height: H, durationInFrames } = useSceneConfig();
  const tl = useTimeline(
    mvpCardTimeline,
    props,
    durationInFrames * speed,
    timing,
  );
  const driftEl = tl.get("drift");
  const cardEl = tl.get("card");
  const sweepEl = tl.get("sweep");
  const titleEl = tl.get("title");
  const nameEl = tl.get("name");
  const kickerEl = tl.get("kicker");
  const c = THEMES[theme];
  const fg = ink ?? c.ink;
  const bg =
    background === "transparent" ? "transparent" : (background ?? c.stage);
  const u = Math.min(W / 1280, H / 720);

  // ── Layout ────────────────────────────────────────────────────────────────
  const cardW = 384 * u;
  const cardH = 628 * u;
  const cardX = W / 2 - 576 * u;
  const cardY = (H - cardH) / 2;
  const pad = 26 * u;
  const portraitH = 236 * u;
  const nameH = 86 * u;
  const rowH =
    (cardH - portraitH - nameH - pad * 0.6) / Math.max(1, stats.length);
  const corner = 34 * u;

  const titleLeft = cardX + cardW + 40 * u;
  const titleRight = W - 48 * u;
  const letters = Array.from(title.toUpperCase());
  const track = -0.01;
  const advSum = letters.reduce(
    (a, ch) => a + (ADV[ch] ?? 0.45) + track,
    -track,
  );
  const titleFs = Math.min(560 * u, (titleRight - titleLeft) / advSum);
  const letterX: number[] = [];
  letters.reduce((x, ch) => {
    letterX.push(x);
    return x + ((ADV[ch] ?? 0.45) + track) * titleFs;
  }, 0);
  const titleW = advSum * titleFs;
  const capBottom = cardY + cardH;

  // ── Entrance ──────────────────────────────────────────────────────────────
  const open = SLAM(ramp(t, cardEl.start, cardEl.beat("open")));
  const settle = SLAM(ramp(t, cardEl.start, cardEl.length));
  const cardScale = 1 + 0.07 * (1 - settle);
  const cardLift = (1 - settle) * 46 * u;
  const sweep = interpolate(
    t,
    [sweepEl.start, sweepEl.end],
    [-0.6, 1.6],
    CLAMP,
  );
  const nameIn = OUT(ramp(t, nameEl.start, nameEl.length));
  const kickerIn = OUT(ramp(t, kickerEl.start, kickerEl.length));
  const lettersAt = (i: number) => titleEl.start + i * titleEl.beat("stagger");
  const lastLetter = lettersAt(letters.length - 1) + titleEl.beat("land");
  const cardHit = cardEl.start + cardEl.beat("hit");
  const hitAt = (tt: number) =>
    Math.max(kick(tt - cardHit, 8), kick(tt - lastLetter, 9) * 0.8);
  const hit = hitAt(t);
  // The hits jump up in one frame and ease back, with no clean progress:
  // compare the zoom with the neighbouring frames, weighed by the reach from
  // the centre to the far corner of the copy. While it moves its tilt covers
  // everything inside, so the inner movers skip theirs.
  const reach = Math.hypot(W, H) / 2;
  const hitting =
    Math.abs(hitAt(t + speed) - hit) * 0.012 * reach > 1e-3 ||
    Math.abs(hit - hitAt(t - speed)) * 0.012 * reach > 1e-3;
  const drift = interpolate(t, [driftEl.start, driftEl.end], [0, 8], CLAMP);

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        <div
          style={{
            position: "absolute",
            inset: 0,
            transform: `scale(${1 + 0.012 * hit})${glide(hitting)}`,
          }}
        >
          {/* Kicker and event line, top right. */}
          <div
            style={{
              position: "absolute",
              left: titleLeft + 6 * u,
              top: cardY + 4 * u,
              opacity: kickerIn,
              transform: `translateX(${(1 - kickerIn) * 30 * u}px)`,
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: 14 * u,
                fontFamily,
                fontWeight: 500,
                fontSize: 24 * u,
                lineHeight: 1,
                letterSpacing: "0.22em",
                textTransform: "uppercase",
                color: c.dim,
                whiteSpace: "nowrap",
              }}
            >
              <div
                style={{ width: 30 * u, height: 4 * u, background: accent }}
              />
              {kicker}
            </div>
            <div
              style={{
                marginTop: 14 * u,
                fontFamily,
                fontWeight: 400,
                fontSize: 78 * u,
                lineHeight: 1,
                letterSpacing: "-0.01em",
                textTransform: "uppercase",
                color: fg,
                whiteSpace: "nowrap",
              }}
            >
              {event}
            </div>
          </div>

          {/* The giant title, rising letter by letter, cap bottom on the card bottom. */}
          <div
            style={{
              position: "absolute",
              left: titleLeft,
              width: titleW,
              top: capBottom - (CAP + 0.03) * titleFs,
              height: (CAP + 0.03) * titleFs + 2 * u,
              overflow: "hidden",
            }}
          >
            {letters.map((ch, i) => {
              const p = SLAM(ramp(t, lettersAt(i), titleEl.beat("rise")));
              return (
                <span
                  key={`${i}-${ch}`}
                  style={{
                    position: "absolute",
                    left: letterX[i],
                    top: (CAP + 0.03) * titleFs - BASELINE * titleFs,
                    fontFamily,
                    fontWeight: 500,
                    fontSize: titleFs,
                    lineHeight: 1,
                    backgroundImage: c.title(drift),
                    backgroundSize: `${titleW}px ${titleFs * 1.1}px`,
                    backgroundPosition: `${-letterX[i]}px ${0.1 * titleFs}px`,
                    backgroundRepeat: "no-repeat",
                    WebkitBackgroundClip: "text",
                    backgroundClip: "text",
                    color: "transparent",
                    transform: `translateY(${(1 - p) * (CAP + 0.06) * titleFs}px)`,
                    whiteSpace: "pre",
                  }}
                >
                  {ch}
                </span>
              );
            })}
          </div>

          {/* The card. */}
          <div
            style={{
              position: "absolute",
              left: cardX,
              top: cardY,
              width: cardW,
              height: cardH,
              transform: `translateY(${cardLift}px) scale(${cardScale})${glide(midway(settle) && !hitting)}`,
              clipPath: `inset(${50 * (1 - open)}% 0 ${50 * (1 - open)}% 0)`,
            }}
          >
            <div
              style={{
                position: "absolute",
                inset: 0,
                clipPath: `polygon(0 0, calc(100% - ${corner}px) 0, 100% ${corner}px, 100% 100%, 0 100%)`,
                background: c.card,
                boxShadow: `inset 0 0 0 ${1.5 * u}px ${c.edge}`,
                overflow: "hidden",
              }}
            >
              {/* Portrait: the R mark as the player. */}
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  width: cardW,
                  height: portraitH,
                  overflow: "hidden",
                  background: [
                    `radial-gradient(70% 80% at ${78 - drift}% 18%, ${FLUTED[2]} 0%, transparent 62%)`,
                    `radial-gradient(60% 70% at ${70 - drift * 0.5}% 6%, ${FLUTED[3]}cc 0%, transparent 46%)`,
                    `radial-gradient(90% 90% at ${14 + drift}% 96%, ${FLUTED[1]} 0%, transparent 70%)`,
                    `linear-gradient(160deg, #B2507A 0%, ${FLUTED[0]} 100%)`,
                  ].join(", "),
                }}
              >
                <svg
                  viewBox="0 0 124.06 134.26"
                  height={234 * u}
                  width={(234 * u * 124.06) / 134.26}
                  style={{
                    position: "absolute",
                    left: cardW / 2 - (234 * u * 124.06) / 134.26 / 2 + 6 * u,
                    bottom: -26 * u,
                    transform: `translateY(${(1 - nameIn) * 30 * u}px)`,
                  }}
                  aria-hidden
                >
                  <path fill="#FFFFFF" d={REMOCN_R_PATH} />
                </svg>
                <div
                  style={{
                    position: "absolute",
                    left: pad,
                    top: pad - 4 * u,
                    fontFamily,
                    fontWeight: 500,
                    fontSize: 64 * u,
                    lineHeight: 1,
                    letterSpacing: "-0.01em",
                    color: "#FFFFFF",
                    fontVariantNumeric: "tabular-nums",
                  }}
                >
                  {number}
                </div>
              </div>

              {/* Name row. */}
              <div
                style={{
                  position: "absolute",
                  left: pad,
                  right: pad,
                  top: portraitH,
                  height: nameH,
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  borderBottom: `${1.5 * u}px solid ${c.rule}`,
                  opacity: nameIn,
                  transform: `translateX(${(1 - nameIn) * 24 * u}px)`,
                }}
              >
                {logo ?? <RemocnLogo fontSize={54 * u} color={fg} />}
                <div
                  style={{
                    display: "flex",
                    alignItems: "center",
                    gap: 10 * u,
                    height: 36 * u,
                    padding: `0 ${14 * u}px`,
                    background: accent,
                    fontFamily,
                    fontWeight: 500,
                    fontSize: 23 * u,
                    letterSpacing: "0.16em",
                    textTransform: "uppercase",
                    color: "#FFFFFF",
                    paddingTop: 2 * u,
                  }}
                >
                  {role}
                </div>
              </div>

              {/* Stats. */}
              {stats.map((s, i) => {
                const stat = tl.get(`stat:${i}`);
                const at = stat.start;
                const statLen = stat.length;
                const p = COUNT(ramp(t, at, statLen));
                const from = s.from ?? 0;
                const v = from + (s.value - from) * p;
                const dec = s.decimals ?? 0;
                const shown = `${v.toFixed(dec)}${s.suffix ?? ""}`;
                const rowIn = OUT(
                  ramp(t, at + stat.beat("rowFrom"), stat.beat("row")),
                );
                const land = kick(t - at - statLen, 9);
                const landing =
                  kick(t + speed - at - statLen, 9) !== land ||
                  kick(t - speed - at - statLen, 9) !== land;
                return (
                  <div
                    key={`${i}-${s.label}`}
                    style={{
                      position: "absolute",
                      left: pad,
                      right: pad,
                      top: portraitH + nameH + i * rowH,
                      height: rowH,
                      display: "flex",
                      alignItems: "center",
                      justifyContent: "space-between",
                      borderBottom:
                        i < stats.length - 1
                          ? `${1.5 * u}px solid ${c.rule}`
                          : "none",
                      opacity: rowIn,
                      transform: `translateY(${(1 - rowIn) * 16 * u}px)${glide(midway(rowIn) && !hitting)}`,
                    }}
                  >
                    <div
                      style={{
                        fontFamily,
                        fontWeight: 500,
                        fontSize: 78 * u,
                        lineHeight: 1,
                        letterSpacing: "-0.01em",
                        fontVariantNumeric: "tabular-nums",
                        color: fg,
                        paddingTop: 4 * u,
                        transform: `scale(${1 + 0.06 * land})${glide(landing && !hitting)}`,
                        transformOrigin: "left center",
                      }}
                    >
                      {shown}
                    </div>
                    <div
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 10 * u,
                        fontFamily,
                        fontWeight: 500,
                        fontSize: 24 * u,
                        letterSpacing: "0.16em",
                        textTransform: "uppercase",
                        color: c.dim,
                      }}
                    >
                      {s.label}
                      <div
                        style={{
                          width: 8 * u,
                          height: 8 * u,
                          background: p >= 1 ? accent : c.rule,
                        }}
                      />
                    </div>
                  </div>
                );
              })}

              {/* Light sweep across the face. */}
              <div
                style={{
                  position: "absolute",
                  top: -cardH * 0.2,
                  height: cardH * 1.4,
                  left: sweep * cardW - cardW * 0.35,
                  width: cardW * 0.7,
                  transform: "skewX(-18deg)",
                  background:
                    "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.5) 46%, rgba(255,255,255,0.75) 50%, rgba(255,255,255,0.5) 54%, rgba(255,255,255,0) 100%)",
                  opacity: sweep > -0.6 && sweep < 1.6 ? 0.85 : 0,
                }}
              />
            </div>
          </div>
        </div>
      </ScaleLayer>
    </AbsoluteFill>
  );
}

